parameters.jsCode:
// A QUIEN LE TOCA EL RECORDATORIO, ITEM POR ITEM.
//
// ESTE NODO NO DECIDE A QUIEN SE LE ESCRIBE. La decision --una sola vez por
// solicitud, nunca a `noContactar`, nunca en operador o bloqueado, nunca a
// quien ya agendo, y solo entre 2 y 4 h o entre 24 y 48 h-- la toma el
// SERVIDOR (`seguimientos.ts`, `esPendienteDeSeguimiento`), que es donde se
// puede probar negando. Aca solo se arma el mensaje.
//
// Y CUANDO NO SE SABE, NO SE ESCRIBE. Misma regla que el flujo de señas
// vencidas: si el panel no contesto 200, si el comercio no esta activo o si
// el listado no vino bien, salen CERO items y no corre ninguna rama. Una hora
// despues se vuelve a intentar; un recordatorio perdido no le cuesta nada a
// nadie, uno mandado de mas cuesta el numero de WhatsApp del cliente.
const base = $('Config base').first().json;
const cfg = $('Traer configuración').first().json ?? {};
const cuerpoCfg = cfg.body ?? {};
const panelContesto = Number(cfg.statusCode) === 200 && typeof cuerpoCfg.tenantId === 'string';
if (!panelContesto || String(cuerpoCfg.estadoComercio || '') !== 'activo') return [];

const lista = $input.first().json ?? {};
if (Number(lista.statusCode) !== 200) return [];
const pendientes = Array.isArray((lista.body || {}).pendientes) ? lista.body.pendientes : [];
if (!pendientes.length) return [];

const negocio = String(((cuerpoCfg.datosDelNegocio || {}).nombreNegocio) || '').trim() || 'la clínica';
const phoneNumberId = String(cuerpoCfg.phoneNumberId || base.phoneNumberId || '');

// America/La_Paz es UTC-4 FIJO (CLAUDE.md): no hay horario de verano, asi que
// restar cuatro horas al instante en UTC da la fecha local, sin depender de la
// zona del contenedor de n8n.
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio',
  'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const fechaEnLaPaz = (iso) => {
  const ms = Date.parse(String(iso || ''));
  if (!Number.isFinite(ms)) return 'los últimos días';
  const d = new Date(ms - 4 * 3600000);
  return `el ${d.getUTCDate()} de ${MESES[d.getUTCMonth()]}`;
};

const out = [];
for (const p of pendientes) {
  const telefono = String((p && p.telefono) || '').replace(/[^0-9]/g, '');
  const modo = String((p && p.modo) || '');
  if (!/^[0-9]{8,15}$/.test(telefono) || (modo !== 'texto' && modo !== 'plantilla')) continue;

  // El nombre lo escribio el cliente en su perfil de WhatsApp: DATO NO
  // CONFIABLE. Se recorta y se le quitan los saltos de linea antes de entrar
  // en un mensaje; nunca se interpola entero.
  const nombre = String((p && p.nombreContacto) || '').replace(/\s+/g, ' ').trim().slice(0, 40);
  const saludo = nombre ? `Hola ${nombre} 👋` : 'Hola 👋';
  const etapa = String((p && p.etapa) || '');
  const fechaSolicitud = fechaEnLaPaz(p && p.ultimoEn);

  // EL TEXTO NO LLEVA NINGUN PRECIO, y es deliberado: el importe de la seña
  // llega en `importe` y NO se escribe. Un recordatorio con una cifra se lee
  // como una oferta --que es justo lo que Meta clasifica como marketing-- y
  // el paciente ya tiene el monto en el caption del QR que recibio.
  const texto = etapa === 'qr_enviado'
    ? `${saludo} Tu solicitud de cita en ${negocio} quedó a la espera de la seña. Si ya la pagaste, mándame el comprobante por acá y lo reviso; si prefieres otro horario, dime y lo vemos.`
    : `${saludo} Te pasé los horarios disponibles en ${negocio} y no alcanzamos a confirmar tu cita. Si todavía te sirve alguno, dime cuál y lo reservo.`;

  // Lo que se reporta a la ingesta cuando el modo es plantilla: el cuerpo de
  // `solicitud_cita_sin_confirmar` ya resuelto, para que la consola muestre lo
  // que la persona recibio y no el nombre de una plantilla.
  const textoPlantilla = `Se registró tu solicitud de cita en ${negocio} para ${fechaSolicitud}. Estado: sin confirmar. Responde este mensaje si quieres retomarla.`;

  out.push({ json: {
    telefono,
    nombre,
    etapa,
    modo,
    nombreNegocio: negocio,
    fechaSolicitud,
    phoneNumberId,
    waGraphVersion: String(base.waGraphVersion || 'v26.0'),
    plantilla: String(base.plantilla || ''),
    idiomaPlantilla: String(base.idiomaPlantilla || 'es'),
    // `texto` es lo que se ENVIA en modo texto; `textoReportado` es lo que se
    // le cuenta a la ingesta en los dos modos.
    texto,
    textoReportado: modo === 'plantilla' ? textoPlantilla : texto,
  } });
}
return out;

