={{ JSON.stringify({
  messaging_product: 'whatsapp',
  to: $('Un item por solicitud').item.json.telefono,
  type: 'template',
  template: {
    name: $('Un item por solicitud').item.json.plantilla,
    language: { code: $('Un item por solicitud').item.json.idiomaPlantilla || 'es' },
    components: [{ type: 'body', parameters: [
      { type: 'text', text: String($('Un item por solicitud').item.json.nombreNegocio || '') },
      { type: 'text', text: String($('Un item por solicitud').item.json.fechaSolicitud || '') },
    ] }],
  },
}) }}
